import type { H3Event } from 'h3'

interface AuthUser {
  id: string
  email?: string
  authMethod: 'session' | 'pat'
}

declare module 'h3' {
  interface H3EventContext {
    user?: AuthUser
  }
}

export type { AuthUser }

export function requireUser(event: H3Event): AuthUser {
  const user = event.context.user
  if (!user) {
    throw createError({ statusCode: 401, statusMessage: 'Unauthorized' })
  }
  return user
}

export function requireSessionUser(event: H3Event): AuthUser {
  const user = requireUser(event)
  if (user.authMethod !== 'session') {
    throw createError({
      statusCode: 403,
      statusMessage: 'This endpoint requires session authentication',
    })
  }
  return user
}

export async function hashToken(rawToken: string): Promise<string> {
  const encoder = new TextEncoder()
  const data = encoder.encode(rawToken)
  const hashBuffer = await crypto.subtle.digest('SHA-256', data)
  const hashArray = Array.from(new Uint8Array(hashBuffer))
  return hashArray.map((b) => b.toString(16).padStart(2, '0')).join('')
}

export function generateToken(): string {
  const bytes = new Uint8Array(32)
  crypto.getRandomValues(bytes)
  const hex = Array.from(bytes)
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('')
  return `nusk_${hex}`
}

import { serverSupabaseUser, serverSupabaseServiceRole } from '#supabase/server'
import type { Database } from '@nusk/shared'

export default defineEventHandler(async (event) => {
  const path = getRequestURL(event).pathname
  if (!path.startsWith('/api/v1/')) return

  try {
    const user = await serverSupabaseUser(event)
    if (user) {
      event.context.user = {
        id: user.id,
        email: user.email,
        authMethod: 'session',
      }
      return
    }
  } catch {
    // Session auth failed, try PAT
  }

  const authHeader = getRequestHeader(event, 'authorization')
  if (!authHeader?.startsWith('Bearer ')) {
    throw createError({ statusCode: 401, statusMessage: 'Unauthorized' })
  }

  const rawToken = authHeader.slice(7)
  const tokenHash = await hashToken(rawToken)

  const client = serverSupabaseServiceRole<Database>(event)
  const { data: pat, error } = await client
    .from('personal_access_tokens')
    .select('id, user_id')
    .eq('token_hash', tokenHash)
    .single()

  if (error || !pat) {
    throw createError({ statusCode: 401, statusMessage: 'Invalid token' })
  }

  client
    .from('personal_access_tokens')
    .update({ last_used_at: new Date().toISOString() })
    .eq('id', pat.id)
    .then()

  event.context.user = {
    id: pat.user_id,
    authMethod: 'pat',
  }
})

import type { H3Event } from 'h3'
import { serverSupabaseClient, serverSupabaseServiceRole } from '#supabase/server'
import type { Database } from '@nusk/shared'
import type { SupabaseClient } from '@supabase/supabase-js'

/**
 * Returns a Supabase client scoped to the authenticated user.
 * For session auth, uses the session-scoped client (RLS applies).
 * For PAT auth, uses the service role client (RLS bypassed, user_id must be filtered manually).
 */
export async function getSupabaseClient(event: H3Event): Promise<{
  client: SupabaseClient<Database>
  userId: string
  isPat: boolean
}> {
  const user = requireUser(event)
  const isPat = user.authMethod === 'pat'

  const client = isPat
    ? serverSupabaseServiceRole<Database>(event)
    : await serverSupabaseClient<Database>(event)

  return { client, userId: user.id, isPat }
}

export default defineEventHandler(async (event) => {
  const { client, userId, isPat } = await getSupabaseClient(event)
  const body = await readBody(event)

  if (!body?.title || typeof body.title !== 'string') {
    throw createError({ statusCode: 400, statusMessage: 'title is required' })
  }

  let listId: string = body.list_id
  if (!listId) {
    const inboxQuery = client
      .from('lists')
      .select('id')
      .eq('is_inbox', true)
      .single()

    if (isPat) inboxQuery.eq('user_id', userId)

    const { data: inbox, error: inboxError } = await inboxQuery

    if (inboxError || !inbox) {
      throw createError({
        statusCode: 404,
        statusMessage: 'Inbox list not found. Please create one first.',
      })
    }
    listId = inbox.id
  }

  let statusId: string = body.status_id
  if (!statusId) {
    const statusQuery = client
      .from('statuses')
      .select('id')
      .eq('list_id', listId)
      .eq('category', 'TODO')
      .order('sort_order', { ascending: true })
      .limit(1)
      .single()

    const { data: defaultStatus, error: statusError } = await statusQuery

    if (statusError || !defaultStatus) {
      throw createError({
        statusCode: 404,
        statusMessage: 'Default status not found for the target list.',
      })
    }
    statusId = defaultStatus.id
  }

  const insertData = {
    user_id: userId,
    list_id: listId,
    status_id: statusId,
    title: body.title,
    scheduled_date: body.scheduled_date ?? null,
    reminder_time: body.reminder_time ?? null,
    recurrence_rule: body.recurrence_rule ?? null,
    metadata: body.metadata ?? {},
    sort_order: body.sort_order ?? 0,
  }

  const { data: task, error } = await client
    .from('tasks')
    .insert(insertData)
    .select()
    .single()

  if (error) {
    throw createError({ statusCode: 500, statusMessage: error.message })
  }

  setResponseStatus(event, 201)
  return task
})

export default defineEventHandler(async (event) => {
  const { client, userId, isPat } = await getSupabaseClient(event)
  const query = getQuery(event)

  let builder = client
    .from('tasks')
    .select('*')
    .is('deleted_at', null)
    .order('sort_order', { ascending: true })

  if (isPat) {
    builder = builder.eq('user_id', userId)
  }

  if (query.list_id && typeof query.list_id === 'string') {
    builder = builder.eq('list_id', query.list_id)
  }

  if (query.scheduled_date && typeof query.scheduled_date === 'string') {
    builder = builder.eq('scheduled_date', query.scheduled_date)
  }

  if (query.status_id && typeof query.status_id === 'string') {
    builder = builder.eq('status_id', query.status_id)
  }

  const { data: tasks, error } = await builder

  if (error) {
    throw createError({ statusCode: 500, statusMessage: error.message })
  }

  return tasks
})

