export default defineEventHandler(async (event) => {
  const { client, userId, isPat } = await getSupabaseClient(event)
  const id = getRouterParam(event, 'id')

  if (!id) {
    throw createError({ statusCode: 400, statusMessage: 'Task ID is required' })
  }

  const body = await readBody(event)
  if (!body || Object.keys(body).length === 0) {
    throw createError({ statusCode: 400, statusMessage: 'Request body is required' })
  }

  const allowedFields = [
    'title',
    'status_id',
    'list_id',
    'scheduled_date',
    'reminder_time',
    'recurrence_rule',
    'metadata',
    'sort_order',
    'deleted_at',
  ] as const

  const updateData: Record<string, unknown> = {
    updated_at: new Date().toISOString(),
  }

  for (const field of allowedFields) {
    if (field in body) {
      updateData[field] = body[field]
    }
  }

  let builder = client
    .from('tasks')
    .update(updateData)
    .eq('id', id)
    .select()
    .single()

  if (isPat) {
    builder = builder.eq('user_id', userId)
  }

  const { data: task, error } = await builder

  if (error) {
    throw createError({ statusCode: error.code === 'PGRST116' ? 404 : 500, statusMessage: error.message })
  }

  return task
})

import { serverSupabaseServiceRole } from '#supabase/server'
import type { Database } from '@nusk/shared'

export default defineEventHandler(async (event) => {
  const user = requireSessionUser(event)
  const body = await readBody(event)

  if (!body?.name || typeof body.name !== 'string') {
    throw createError({ statusCode: 400, statusMessage: 'name is required' })
  }

  const rawToken = generateToken()
  const tokenHash = await hashToken(rawToken)

  const client = serverSupabaseServiceRole<Database>(event)
  const { data: pat, error } = await client
    .from('personal_access_tokens')
    .insert({
      user_id: user.id,
      token_hash: tokenHash,
      name: body.name,
    })
    .select('id, name, created_at')
    .single()

  if (error) {
    throw createError({ statusCode: 500, statusMessage: error.message })
  }

  setResponseStatus(event, 201)
  return {
    ...pat,
    token: rawToken,
  }
})

import { serverSupabaseServiceRole } from '#supabase/server'
import type { Database } from '@nusk/shared'

export default defineEventHandler(async (event) => {
  const user = requireSessionUser(event)

  const client = serverSupabaseServiceRole<Database>(event)
  const { data: tokens, error } = await client
    .from('personal_access_tokens')
    .select('id, name, created_at, last_used_at')
    .eq('user_id', user.id)
    .order('created_at', { ascending: false })

  if (error) {
    throw createError({ statusCode: 500, statusMessage: error.message })
  }

  return tokens
})

